const IMOFLOW_LOGO_WHITE_DATA = "data:image/png;base64,";
const IMOFLOW_LOGO_COLOR_DATA = "data:image/png;base64,";
window.IMOFLOW_LOGO_DATA = IMOFLOW_LOGO_COLOR_DATA;
document.querySelector(".brand-agency-logo")?.setAttribute("src", IMOFLOW_LOGO_WHITE_DATA);
async function imoflowInflate(payload) {
  const bytes = Uint8Array.from(atob(payload), char => char.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return await new Response(stream).text();
}
(async () => {
  const css = await imoflowInflate("");
  const style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);
  eval(await imoflowInflate(""));
  eval(await imoflowInflate(""));

})().catch(error => {
  console.error(error);
  document.getElementById("mainContent").innerHTML = '<div class="empty-state">Não foi possível iniciar o ImoFlow neste navegador.</div>';
});
